style.css:
body {
    background-image: url("https://imgur.com/gallery/seaside-stormbreakers-hchl-OkurR4g") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
}

/* Dark overlay for readability */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.6);
    pointer-events: none;
    z-index: -1;
}
